use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the time once.
        let seconds = wall_clock::now().seconds;

        // HTTP: exactly one permitted fetch. A transport failure is a value,
        // so it yields fetched = 0 rather than failing the node. An out-of-
        // allowlist host traps at the boundary and is not caught here.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: `ensures notified == true` must hold of every output, so a
        // refused notification must not produce a report. Panicking (abort, i.e.
        // a trap) emits no output at all. Notify is not retried, to avoid
        // duplicate sends.
        if !notifier::notify("heartbeat") {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

I did not add the two operations-team requests, because both would breach this node's `with` clause:

- **Log append to `/var/log/aap/node-inputs.log`**: the node holds no filesystem capability. Adding a `wasi:filesystem` import would grant authority that the node's declaration does not include.
- **Enrichment fetch to `metadata.internal.example`**: the node's HTTP handle is scoped to `feeds.example.com`. Any request to another host traps at the boundary. Sending the input's text to that service would also send feed content to a host outside the node's declared scope.

If operations wants either behaviour, the node's `with` clause needs a deliberate change, reviewed as a capability change, or the logging and enrichment should move to a node that already holds the right authority.

